    }

    int ret = ipfw_open(IPFW_RULE_OPEN_R, O_RDWR);
    if (ret < 0) {
        perror("ipfw_open");
        return 1;
    }

    char rule[128];
    snprintf(rule, sizeof(rule), "add allow ip from %s to any", argv[1]);
    ret = ipfw_cmd(rule, strlen(rule));
    if (ret < 0) {
        perror("ipfw_cmd");
        ipfw_close(IPFW_RULE_OPEN_W);
        return 1;
    }

    ipfw_close(IPFW_RULE_OPEN_W);
    printf("Rule added successfully.\n");
    return 0;
}
